import math
from collections.abc import Mapping, Sequence


class SignalDataset:
    PARTITIONS = ("train", "validation", "test")

    def __init__(self, labels=("calm", "bright", "rough"), stride=2):
        if isinstance(labels, (str, bytes)) or not isinstance(labels, Sequence):
            raise ValueError("labels must be a sequence")
        copied = tuple(labels)
        if not copied or any(not isinstance(x, str) or not x for x in copied) or len(set(copied)) != len(copied):
            raise ValueError("invalid labels")
        if isinstance(stride, bool) or not isinstance(stride, int) or stride < 1:
            raise ValueError("invalid stride")
        self.labels = copied
        self.stride = stride

    def encode(self, label):
        if not isinstance(label, str) or label not in self.labels:
            raise ValueError("unknown label")
        return tuple(1 if item == label else 0 for item in self.labels)

    def features(self, samples):
        if isinstance(samples, (str, bytes)) or not isinstance(samples, Sequence) or not samples:
            raise ValueError("samples must be nonempty")
        values = []
        for value in samples:
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
                raise ValueError("invalid sample")
        values = [float(samples[i]) for i in range(0, len(samples), self.stride)]
        mean = sum(values) / len(values)
        span = max(values) - min(values)
        if len(values) == 1:
            return (mean, span, 0.0, 0.0)
        pairs = list(zip(values, values[1:]))
        crossings = sum((a <= 0 <= b) or (b <= 0 <= a) for a, b in pairs)
        return (mean, span, crossings / len(pairs), sum(abs(b - a) for a, b in pairs) / len(pairs))

    def preprocess(self, partitions):
        if not isinstance(partitions, Mapping) or set(partitions) != set(self.PARTITIONS):
            raise ValueError("invalid partitions")
        output = {}
        for name in self.PARTITIONS:
            rows = partitions[name]
            if isinstance(rows, (str, bytes)) or not isinstance(rows, Sequence):
                raise ValueError("partition must be a sequence")
            fs, ys = [], []
            for row in rows:
                if isinstance(row, (str, bytes)) or not isinstance(row, Sequence) or len(row) != 2:
                    raise ValueError("invalid row")
                fs.append(self.features(row[1]))
                ys.append(self.encode(row[0]))
            output[name] = {"features": tuple(fs), "labels": tuple(ys)}
        return output

    def deserialize(self, data):
        if not isinstance(data, Mapping) or set(data) != set(self.PARTITIONS):
            raise ValueError("invalid data")
        output = {}
        for name in self.PARTITIONS:
            block = data[name]
            if not isinstance(block, Mapping) or set(block) != {"features", "labels"}:
                raise ValueError("invalid block")
            fs, ys = block["features"], block["labels"]
            if not isinstance(fs, Sequence) or isinstance(fs, (str, bytes)) or not isinstance(ys, Sequence) or isinstance(ys, (str, bytes)) or len(fs) != len(ys):
                raise ValueError("invalid rows")
            new_f, new_y = [], []
            for feature, label in zip(fs, ys):
                if not isinstance(feature, Sequence) or isinstance(feature, (str, bytes)) or len(feature) != 4 or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in feature):
                    raise ValueError("invalid feature row")
                if not isinstance(label, Sequence) or isinstance(label, (str, bytes)) or len(label) != len(self.labels) or any(type(x) is not int or x not in (0, 1) for x in label) or sum(label) != 1:
                    raise ValueError("invalid label row")
                new_f.append([float(x) for x in feature])
                new_y.append(list(label))
            output[name] = {"features": new_f, "labels": new_y}
        return output

